//! Bridge between the Flutter UI and the Rustle3D core.
//!
//! The UI is a thin client: it sends the same JSON steps as the CLI and the
//! MCP server (commands, queries, actions, undo/redo) and receives JSON
//! results or structured errors. Dart bindings are generated by
//! `flutter_rust_bridge_codegen generate` (run in `app/`) from [`api`].

pub mod api;

// Generated glue: raw FFI entry points, hence `unsafe`. Left as the
// generator formats it, so regenerating never produces formatting diffs.
#[allow(unsafe_code)]
#[rustfmt::skip]
mod frb_generated;
